const OUT = { month: new Date().toISOString().slice(0, 7), cp: '' };
function outMonthInvoices(month) {
return invoices.filter(row => row.date.startsWith(month) && (!scope || row.from.rfc === scope || row.to.rfc === scope));
}
function ivaRows(month) {
return people.map(person => {
let issuedIva = 0n, receivedIva = 0n, issuedCount = 0, receivedCount = 0, missing = 0;
for (const row of invoices) {
if (!row.date.startsWith(month) || row.kind !== 'I' || (row.currency && row.currency !== 'MXN')) continue;
const iva = invoiceIvaCents(row);
if (row.from.rfc === person.id) { issuedCount++; if (iva === null) missing++; else issuedIva += iva; }
if (row.to.rfc === person.id) { receivedCount++; if (iva === null) missing++; else receivedIva += iva; }
}
return { rfc: person.id, name: person.name, issuedIva, receivedIva, issuedCount, receivedCount, missing,
balance: issuedIva - receivedIva };
}).filter(row => row.issuedCount || row.receivedCount);
}
function salidasScreen() {
const wrap = n('div');

const ivaPanel = panel('IVA del mes por RFC', 'IVA trasladado (lo que cobraste) e IVA acreditable (lo que te facturaron), desde el desglose guardado de cada XML. Si falta desglose, reprocésalo abajo: nunca se estima a ojo.');
const monthRow = n('div', undefined, 'filterbar');
const monthInput = input('month', { value: OUT.month, 'aria-label': 'Mes' });
monthInput.onchange = () => { OUT.month = monthInput.value || OUT.month; render(); };
monthRow.append(n('label', 'Mes '), monthInput);
ivaPanel.append(monthRow);
const rows = ivaRows(OUT.month);
if (!rows.length) ivaPanel.append(n('p', 'Sin CFDI de ingreso en ese mes para tus RFC.', 'empty'));
else ivaPanel.append(grid(['RFC', 'IVA trasladado', 'IVA acreditable', 'Saldo del mes', 'CFDI sin desglose'],
rows.map(row => [cell(row.name || row.rfc, row.rfc),
'$' + centsLabel(row.issuedIva), '$' + centsLabel(row.receivedIva),
(row.balance >= 0n ? 'A pagar ≈ $' : 'A favor ≈ $') + centsLabel(row.balance < 0n ? -row.balance : row.balance),
row.missing ? row.missing + ' (reprocesa)' : '—'])));
const reparseBtn = n('button', 'Reprocesar XML guardados (completar desglose)', 'soft');
reparseBtn.onclick = async () => {
reparseBtn.disabled = true; reparseBtn.textContent = 'Reprocesando…';
try {
if (satToken) {
const result = await satApi('reparse', {});
toast('Re-parseo: ' + result.updated + ' completados, ' + result.skipped + ' ya tenían desglose, ' + result.failed + ' sin XML guardado.', 'ok');
await refresh();
} else {
let updated = 0;
const files = await readStore('files');
const byId = new Map(files.map(file => [file.id, file]));
const changed = [];
for (const row of invoices) {
if (row.fiscal && (row.kind !== 'P' || row.fiscal.payments !== undefined)) continue;
const file = byId.get('xml:' + row.id);
if (!file?.blob) continue;
const before = row.fiscal;
withFiscal(row, new Uint8Array(await file.blob.arrayBuffer()));
if (row.fiscal !== before && row.fiscal) { changed.push(row); updated++; }
}
if (changed.length) await writeBatch({ invoices: changed });
toast('Re-parseo local: ' + updated + ' CFDI completados con su desglose.', 'ok');
await refresh();
}
render();
} catch (error) { toast(error.message, 'error'); reparseBtn.disabled = false; reparseBtn.textContent = 'Reprocesar XML guardados (completar desglose)'; }
};
ivaPanel.append(reparseBtn);
wrap.append(ivaPanel);

const reportPanel = panel('Reporte del periodo', 'Totales del mes por sentido y por contraparte, con su IVA. Se puede imprimir, bajar en CSV o enviar por correo desde aquí.');
const cpInput = input('search', { placeholder: 'Filtrar por contraparte (nombre o RFC)…', value: OUT.cp, 'aria-label': 'Contraparte' });
cpInput.onchange = () => { OUT.cp = cpInput.value; render(); };
reportPanel.append(cpInput);
const monthInvoices = outMonthInvoices(OUT.month).filter(row =>
!OUT.cp || (row.from.name + row.from.rfc + row.to.name + row.to.rfc).toLowerCase().includes(OUT.cp.toLowerCase()));
let issuedTotal = 0n, receivedTotal = 0n, issuedIva = 0n, receivedIva = 0n;
for (const row of monthInvoices) {
if (row.currency && row.currency !== 'MXN') continue;
const role = roles(row), iva = invoiceIvaCents(row);
if (role.issued) { issuedTotal += totalCents(row); if (iva !== null) issuedIva += iva; }
if (role.received) { receivedTotal += totalCents(row); if (iva !== null) receivedIva += iva; }
}
reportPanel.append(grid(['Concepto', 'Importe'], [
['CFDI emitidos (' + monthInvoices.filter(row => roles(row).issued).length + ')', '$' + centsLabel(issuedTotal)],
['IVA trasladado del mes', '$' + centsLabel(issuedIva)],
['CFDI recibidos (' + monthInvoices.filter(row => roles(row).received).length + ')', '$' + centsLabel(receivedTotal)],
['IVA acreditable del mes', '$' + centsLabel(receivedIva)]
]));
const reportActions = n('div', undefined, 'sat-actions');
const printBtn = n('button', 'Imprimir reporte', 'soft');
printBtn.onclick = () => printPeriodReport(OUT.month, monthInvoices, { issuedTotal, receivedTotal, issuedIva, receivedIva });
const csvBtn = n('button', 'Descargar CSV del mes', 'soft');
csvBtn.onclick = () => download(new Blob(['\uFEFF', periodCsv(OUT.month)], { type: 'text/csv;charset=utf-8' }), 'reporte-' + OUT.month + '.csv');
const mailBtn = n('button', 'Enviar por correo', 'soft');
mailBtn.onclick = () => composeMailDialog({ subject: 'PacoSAT · Reporte ' + OUT.month,
text: 'Adjunto el reporte del mes ' + OUT.month + ' generado por PacoSAT.',
attachments: [{ filename: 'reporte-' + OUT.month + '.csv', content: encode64(new TextEncoder().encode(periodCsv(OUT.month))) }] });
reportActions.append(printBtn, csvBtn, mailBtn);
reportPanel.append(reportActions);
wrap.append(reportPanel);



if (satToken) wrap.append(salidasDisenadasPanel());
else wrap.append(panel('Salidas por destino (PDF y Excel)', 'Los PDF de papel y los Excel reales los construye el servidor de PacoSAT: conecta la app en modo servidor (NAS) para descargarlos desde aquí.'));


if (satToken) wrap.append(manoFilPanel());

wrap.append(yoyPanel());




const cierrePointer = panel('Cierre del mes', 'La lista de pasos del cierre, con su estado y el camino a resolver cada uno, vive en su pestaña.');
cierrePointer.append(action('Abrir el cierre guiado', () => { cierreSection = 'cierre'; render(); }, 'primary', 'check'));
wrap.append(cierrePointer);

if (satToken) { wrap.append(mailPanel()); wrap.append(autoReportsPanel()); }
else wrap.append(panel('Correo e informes automáticos', 'En modo local sin servidor, el correo automático no está disponible: conecta PacoSAT en modo servidor (NAS) para enviar informes y correos desde la app.'));

const exportPanel = panel('Exportación completa legible', 'Todos tus XML y PDF en carpetas por RFC y año, con su índice CSV. Independiente del respaldo cifrado: tus datos salen enteros cuando quieras.');
const exportActions = n('div', undefined, 'sat-actions');
const exportAll = n('button', 'Exportar todo', 'soft');
exportAll.onclick = () => exportFull('');
const yearNow = new Date().getFullYear();
const exportYear = n('button', 'Exportar ' + yearNow, 'soft');
exportYear.onclick = () => exportFull(String(yearNow));
exportActions.append(exportAll, exportYear);
exportPanel.append(exportActions);
wrap.append(exportPanel);
return [wrap];
}



async function salidaDescargar(ruta, payload, boton) {
const texto = boton ? boton.textContent : '';
if (boton) { boton.disabled = true; boton.textContent = 'Preparando…'; }
try {
const data = await satApi(ruta, payload);
download(new Blob([decode64(data.content)], { type: data.type || 'application/octet-stream' }), data.name);
toast('Salida lista: ' + data.name, 'ok');
} catch (error) { toast(error.message, 'error'); }
finally { if (boton) { boton.disabled = false; boton.textContent = texto; } }
}




function salidasDisenadasPanel() {
const panelEl = panel('Salidas por destino', 'Artefactos pensados para quien los recibe, no volcados de pantalla: PDF A4 con folio y totales para imprimir o enviar, Excel real con importes como números, filtros y sumas, y ZIP ordenados por carpetas con su índice. Todo sale del mes y el RFC elegidos arriba.');
const rfc = () => scope || people[0]?.id || '';
const destinos = [
['Para tu contadora', [
['PDF de cierre mensual', 'salidas/pdf', () => ({ kind: 'cierre', rfc: rfc(), month: OUT.month }), 'pdf:cierre'],
['ZIP de cierre (con constancia y opinión)', 'salidas/zip', () => ({ scope: 'cierre', rfc: rfc(), month: OUT.month }), 'zip:cierre'],
['PDF del periodo', 'salidas/pdf', () => ({ kind: 'periodo', rfc: rfc(), month: OUT.month }), 'pdf:periodo'],
['ZIP del periodo', 'salidas/zip', () => ({ scope: 'periodo', rfc: rfc(), month: OUT.month }), 'zip:periodo'],
['Excel de facturas', 'salidas/xlsx', () => ({ kind: 'facturas', rfc: rfc(), month: OUT.month }), 'xlsx:facturas']]],
['Para el banco', [
['Excel de pagos al banco', 'salidas/xlsx', () => ({ kind: 'pagos', rfc: rfc() }), 'xlsx:pagos'],
['PDF de saldos', 'salidas/pdf', () => ({ kind: 'saldos', rfc: rfc() }), 'pdf:saldos'],
['Excel de saldos por cobrar', 'salidas/xlsx', () => ({ kind: 'saldos-cobrar', rfc: rfc() }), 'xlsx:saldos'],
['Excel de saldos por pagar', 'salidas/xlsx', () => ({ kind: 'saldos-pagar', rfc: rfc() }), 'xlsx:saldos']]],
['Para ti', [
['PDF del mapa anual de declaraciones', 'salidas/pdf', () => ({ kind: 'declaraciones', rfc: rfc(), year: OUT.month.slice(0, 4) }), 'pdf:declaraciones'],
['Excel de complementos de pago', 'salidas/xlsx', () => ({ kind: 'complementos', rfc: rfc() }), 'xlsx:complementos'],
['Excel de listados del SAT', 'salidas/xlsx', { kind: 'listados' }, 'xlsx:listados'],
['ZIP de todo el RFC', 'salidas/zip', () => ({ scope: 'rfc', rfc: rfc(), year: OUT.month.slice(0, 4) }), 'zip:rfc']]]
];
for (const [titulo, salidas] of destinos) {
const card = n('div', undefined, 'kpi');
card.append(n('strong', titulo));
for (const [label, ruta, payload, clave] of salidas) {
const fila = n('div', undefined, 'cp-row');
const btn = n('button', label, 'soft');
btn.onclick = () => salidaDescargar(ruta, typeof payload === 'function' ? payload() : payload, btn);
const ultima = n('span', 'Sin generar todavía', 'muted');
ultima.dataset.salidaUltima = clave;
fila.append(btn, ultima);
card.append(fila);
}
panelEl.append(card);
}
(async () => {
const last = await satApi('salidas/last').catch(() => null);
if (!last || !panelEl.isConnected) return;
for (const el of panelEl.querySelectorAll('[data-salida-ultima]')) {
const at = last[el.dataset.salidaUltima];
if (at) el.textContent = 'Última generación: ' + localDate(at);
}
})();


const cps = new Map();
for (const row of invoices) {
if (scope && row.from.rfc !== scope && row.to.rfc !== scope) continue;
const cp = row.from.rfc === scope ? row.to : row.from;
if (cp?.rfc && cp.rfc !== scope) cps.set(cp.rfc, cp.name || cp.rfc);
}
if (cps.size) {
const row = n('div', undefined, 'sat-actions');
const picker = select([...cps.entries()].map(([value, label]) => [value, label + ' · ' + value]), [...cps.keys()][0], 'Contraparte del reporte');
const btn = n('button', 'PDF por contraparte', 'soft');
btn.onclick = () => salidaDescargar('salidas/pdf', { kind: 'contraparte', rfc: rfc(), contraparte: picker.value }, btn);
row.append(picker, btn);
panelEl.append(row);
}
return panelEl;
}





const MFPERIODO = { mode: 'mes' };
function manoFilPanel() {
const RFC = 'MFI6212158B4';
const panelEl = panel('Reporte Mano Fil', 'El informe del negocio para Rodrigo y José Javier, desde el expediente: cuánto se facturó y cuánto se cobró, los pagos a proveedores con su folio, lo que se debe y a quién, los impuestos presentados, la nómina del periodo y el saldo en bancos. El resumen responde en pocas líneas y el detalle va detrás. Solo datos de Mano Fil.');
if (!people.some(person => person.id === RFC)) {
panelEl.append(n('p', 'El perfil de Mano Fil (' + RFC + ') no está en este expediente: este reporte es solo de ese negocio y no se genera para ningún otro.', 'empty'));
return panelEl;
}
const modo = select([['mes', 'Mes completo'], ['rango', 'Rango de fechas']], MFPERIODO.mode, 'Periodo del reporte');
const modoRow = n('div', undefined, 'filterbar');
modoRow.append(n('label', 'Periodo '), modo);
const mesRow = n('div', undefined, 'filterbar');
mesRow.append(n('span', 'Mes del reporte: '), n('strong', OUT.month), n('span', ' (el mes elegido arriba, en «IVA del mes»)'));
const [anio, mes] = OUT.month.split('-').map(Number);
const ultimoDia = OUT.month + '-' + String(new Date(Date.UTC(anio, mes, 0)).getUTCDate()).padStart(2, '0');
const desde = input('date', { value: OUT.month + '-01', 'aria-label': 'Desde' });
const hasta = input('date', { value: ultimoDia, 'aria-label': 'Hasta' });
const rangoRow = n('div', undefined, 'filterbar');
rangoRow.append(n('label', 'Desde '), desde, n('label', ' Hasta '), hasta);
const sync = () => { const esMes = modo.value === 'mes'; MFPERIODO.mode = modo.value;
mesRow.style.display = esMes ? '' : 'none'; rangoRow.style.display = esMes ? 'none' : ''; };
modo.onchange = sync;
const actions = n('div', undefined, 'sat-actions');
const payload = () => MFPERIODO.mode === 'mes' ? { month: OUT.month } : { from: desde.value, to: hasta.value };
const pdfBtn = n('button', 'Descargar el reporte en PDF', 'primary');
pdfBtn.onclick = () => salidaDescargar('salidas/reporte-manofil', { ...payload(), format: 'pdf' }, pdfBtn);
const xlsxBtn = n('button', 'Descargar el reporte en Excel', 'soft');
xlsxBtn.onclick = () => salidaDescargar('salidas/reporte-manofil', { ...payload(), format: 'xlsx' }, xlsxBtn);
actions.append(pdfBtn, xlsxBtn);
panelEl.append(modoRow, mesRow, rangoRow, actions);
sync();
return panelEl;
}
function periodCsv(month) {
const escape = value => '"' + String(value ?? '').replaceAll('"', '""') + '"';



const rows = [['UUID', 'Folio', 'Fecha', 'Tipo', 'Emisor RFC', 'Emisor', 'Receptor RFC', 'Receptor', 'Subtotal', 'IVA', 'Total', 'Moneda', 'Método de pago']];
for (const row of outMonthInvoices(month)) {
const iva = invoiceIvaCents(row);
const folio = row.fiscal ? (row.fiscal.series ? row.fiscal.series + '-' : '') + (row.fiscal.folio || '') : '';
rows.push([row.id, folio, row.date, row.kind, row.from.rfc, row.from.name, row.to.rfc, row.to.name,
row.fiscal?.subtotal || '', iva === null ? '' : centsPlain(iva), centsPlain(totalCents(row)), row.currency || 'MXN', row.fiscal?.paymentMethod || '']);
}
return rows.map(row => row.map(escape).join(',')).join('\r\n');
}
function printPeriodReport(month, rows, totals) {
const section = $('print-report');
section.replaceChildren();
const head = n('div', undefined, 'report-head');
head.append(n('h1', 'Reporte del periodo ' + month), n('p', installName + (scope ? ' · ' + scope : ' · Sin contribuyente')));
const body = n('div', undefined, 'report-body');
body.append(n('p', 'Emitidos: $' + centsLabel(totals.issuedTotal) + ' (IVA trasladado $' + centsLabel(totals.issuedIva) +
') · Recibidos: $' + centsLabel(totals.receivedTotal) + ' (IVA acreditable $' + centsLabel(totals.receivedIva) + ').'));
const table = n('table');
const thead = n('thead'); const htr = n('tr');
for (const label of ['Fecha', 'Folio', 'UUID', 'Contraparte', 'Tipo', 'Total']) htr.append(n('th', label));
thead.append(htr); table.append(thead);
const tbody = n('tbody');



for (const row of rows) {
const role = roles(row);
const tr = n('tr');
const folio = row.fiscal ? (row.fiscal.series ? row.fiscal.series + '-' : '') + (row.fiscal.folio || '') : 'Sin folio';
tr.append(n('td', row.date), n('td', folio), n('td', row.id),
n('td', (role.issued ? row.to.name : row.from.name) || ''), n('td', row.kind), n('td', money(row.total)));
tbody.append(tr);
}
table.append(tbody);
body.append(table);
body.append(n('p', 'Generado por PacoSAT desde el expediente local. Los importes de IVA salen del desglose guardado de cada XML.'));
section.append(head, body, reportFoot(scope));
setTimeout(() => window.print(), 80);
}
function yoyPanel() {
const panelEl = panel('Comparativas año contra año', 'Quién te factura más que el año pasado y qué se está disparando: totales recibidos y emitidos por contraparte, año actual contra anterior (solo MXN).');
const year = new Date().getFullYear();
const totals = new Map();
for (const row of invoices) {
if ((row.currency && row.currency !== 'MXN') || row.kind !== 'I') continue;
const y = row.date.slice(0, 4);
if (y !== String(year) && y !== String(year - 1)) continue;
for (const [rfc, name, field] of [[row.from.rfc, row.from.name, 'received'], [row.to.rfc, row.to.name, 'issued']]) {
if (scope && rfc === scope) continue;
const key = rfc;
if (!totals.has(key)) totals.set(key, { name: name || rfc, rfc, receivedNow: 0n, receivedPrev: 0n, issuedNow: 0n, issuedPrev: 0n });
const item = totals.get(key);
item[field + (y === String(year) ? 'Now' : 'Prev')] += totalCents(row);
}
}
const rows = [...totals.values()].map(item => ({ ...item,
delta: (item.receivedNow - item.receivedPrev) + (item.issuedNow - item.issuedPrev) }))
.filter(item => item.receivedNow || item.receivedPrev || item.issuedNow || item.issuedPrev)
.sort((a, b) => (b.delta < a.delta ? -1 : b.delta > a.delta ? 1 : 0)).slice(0, 15);
if (!rows.length) { panelEl.append(n('p', 'Aún no hay dos años de datos para comparar.', 'empty')); return panelEl; }
panelEl.append(grid(['Contraparte', 'Recibido ' + (year - 1), 'Recibido ' + year, 'Emitido ' + (year - 1), 'Emitido ' + year, 'Cambio'],
rows.map(item => [cell(item.name, item.rfc), '$' + centsLabel(item.receivedPrev), '$' + centsLabel(item.receivedNow),
'$' + centsLabel(item.issuedPrev), '$' + centsLabel(item.issuedNow),
(item.delta >= 0n ? '+$' : '−$') + centsLabel(item.delta < 0n ? -item.delta : item.delta)])));
return panelEl;
}
function composeMailDialog(preset = {}) {
const to = input('text', { placeholder: 'destinatario@ejemplo.com, otro@ejemplo.com', value: preset.to || '' });
const subject = input('text', { placeholder: 'Asunto', value: preset.subject || '' });
const text = n('textarea', preset.text || '');
text.rows = 6;
const controls = [field('Para', to), field('Asunto', subject), field('Mensaje', text)];
if (preset.attachments?.length) controls.push(n('p', 'Adjuntos: ' + preset.attachments.map(item => item.filename).join(', '), 'muted'));
dialog('Enviar correo desde PacoSAT', controls, async () => {
await satApi('mail/send', { to: to.value, subject: subject.value, text: text.value, attachments: preset.attachments || [] });
toast('Correo enviado y anotado en la bitácora.', 'ok');
if (page === 'salidas') render();
}, 'Enviar correo');
}
function mailPanel() {
const panelEl = panel('Correo desde la app', 'Envía CFDI, reportes o constancias sin salir de PacoSAT. Cada envío queda anotado abajo.');
const compose = n('button', 'Escribir correo', 'primary');
compose.onclick = () => composeMailDialog();
panelEl.append(compose);
const log = n('div');
panelEl.append(log);
(async () => {
try {
const data = await satApi('mail/log');
log.replaceChildren();
if (!data.sends.length) { log.append(n('p', 'Todavía no se ha enviado ningún correo desde la app.', 'muted')); return; }
for (const send of data.sends.slice(0, 20)) {
const row = n('div', undefined, 'cp-row');
row.append(statusPill(send.ok ? 'ok' : 'bad', send.ok ? 'Enviado' : 'Falló'),
n('span', localDateTime(send.at), 'muted'),
n('span', send.subject + ' → ' + send.recipients + (send.error ? ' · ' + send.error : '')));
log.append(row);
}
} catch {  }
})();
return panelEl;
}
function autoReportsPanel() {
const panelEl = panel('Informes automáticos', 'El paquete mensual a la contadora (con base DIOT, novedades de listas y PPD), el resumen semanal de los lunes y el Reporte Mano Fil mensual para Rodrigo y José Javier (se genera solo, queda guardado en Expedientes y sale por correo si lo activas). Se configuran una vez y salen solos.');
const body = n('div');
panelEl.append(body);
const fill = async data => {
const config = data || await satApi('reports/config');
body.replaceChildren();
const build = (key, title, withDay) => {
const item = config[key] || {};
const form = n('div', undefined, 'satdoc-form');
const enabled = input('checkbox', { checked: Boolean(item.enabled) });
const label = n('label', undefined, 'switch-line');
label.append(enabled, n('span', title));
form.append(label);
let dayInput = null;
if (withDay) { dayInput = input('number', { value: item.day || 3, min: 1, max: 28, 'aria-label': 'Día' }); form.append(n('span', 'Día '), dayInput); }
const hourInput = input('number', { value: item.hour ?? 9, min: 0, max: 23, 'aria-label': 'Hora' });
form.append(n('span', ' a las '), hourInput, n('span', ':00'));
const recipients = input('text', { value: item.recipients || '', placeholder: 'Destinatarios (vacío = tu correo de avisos)' });
form.append(recipients);
const save = n('button', 'Guardar', 'soft');
save.onclick = async () => {
const next = { ...config, [key]: { enabled: enabled.checked, day: dayInput ? Number(dayInput.value) : 3,
hour: Number(hourInput.value), recipients: recipients.value } };
try { fill(await satApi('reports/config', next)); toast('Informe automático guardado.', 'ok'); }
catch (error) { toast(error.message, 'error'); }
};
form.append(save);
return form;
};
body.append(build('nora', 'Informe mensual a la contadora', true), build('weekly', 'Resumen semanal (lunes)', false),
build('manofil', 'Reporte Mano Fil mensual (Rodrigo y José Javier)', true));
const nowBtn = n('button', 'Enviar ahora el paquete del mes pasado', 'soft');
nowBtn.onclick = async () => {
const prev = new Date(); prev.setMonth(prev.getMonth() - 1);
const month = prev.toISOString().slice(0, 7);
try {
const result = await satApi('reports/send-now', { month });
toast('Paquete de ' + month + ' enviado a ' + result.recipients + ' (' + result.counts.invoices + ' CFDI).', 'ok');
render();
} catch (error) { toast(error.message, 'error'); }
};
body.append(nowBtn);
const mfBtn = n('button', 'Enviar ahora el Reporte Mano Fil del mes pasado', 'soft');
mfBtn.onclick = async () => {
const prev = new Date(); prev.setMonth(prev.getMonth() - 1);
const month = prev.toISOString().slice(0, 7);
try {
const result = await satApi('reports/send-manofil', { month });
toast('Reporte Mano Fil de ' + month + ' guardado en Expedientes y enviado a ' + result.recipients + '.', 'ok');
} catch (error) { toast(error.message, 'error'); }
};
body.append(mfBtn);
};
fill();
return panelEl;
}
async function exportFull(year) {
try {
if (satToken) {
toast('Preparando la exportación…', 'ok');
const data = await satApi('export-full', { year });
download(new Blob([decode64(data.content)], { type: 'application/zip' }), data.name);
toast('Exportación lista: ' + data.files + ' archivos.', 'ok');
return;
}
const files = await readStore('files');
const byId = new Map(files.map(file => [file.id, file]));
const entries = [];
const index = [['UUID', 'Fecha', 'Emisor RFC', 'Receptor RFC', 'Tipo', 'Total']];
for (const row of invoices) {
const y = row.date.slice(0, 4);
if (year && y !== year) continue;
index.push([row.id, row.date, row.from.rfc, row.to.rfc, row.kind, row.total]);
const file = byId.get('xml:' + row.id);
if (file?.blob) entries.push({ name: row.from.rfc + '/' + y + '/' + row.id + '.xml', data: new Uint8Array(await file.blob.arrayBuffer()) });
}
for (const doc of documents) {
const y = String(doc.date || '').slice(0, 4);
if (year && y !== year) continue;
const file = byId.get(doc.id);
if (file?.blob) entries.push({ name: doc.rfc + '/' + y + '/documentos/' + (doc.name || doc.id), data: new Uint8Array(await file.blob.arrayBuffer()) });
}
const escape = value => '"' + String(value ?? '').replaceAll('"', '""') + '"';
entries.unshift({ name: 'indice.csv', data: new TextEncoder().encode('﻿' + index.map(row => row.map(escape).join(',')).join('\r\n')) });
download(new Blob([zipStore(entries)], { type: 'application/zip' }), 'PacoSAT-exportacion' + (year ? '-' + year : '-completa') + '.zip');
toast('Exportación lista: ' + (entries.length - 1) + ' archivos.', 'ok');
} catch (error) { toast(error.message, 'error'); }
}

pagos.source:
let pagosCatalogo = null, pagosLineas = [], pagosSinCatalogo = [];
let pagosPrep = null, pagosTxt = '', pagosEditando = '';
let pagosSteps = {}, pagosCatBody = null, pagosPrepBodyRef = null, pagosOutBody = null, pagosGenBtn = null;
let pagosGroupInputs = null, pagosAltaPrefill = null, pagosNombreInput = null;
const PAGOS_TOPE = 49999.99;
const PAGOS_CUENTA_KEY = 'pacosat-pagos-cuenta-retiro';
function pagosDigitoClabe(clabe17) {
const pesos = [3, 7, 1];
let suma = 0;
for (let i = 0; i < 17; i++) suma += (Number(clabe17[i]) * pesos[i % 3]) % 10;
return String((10 - (suma % 10)) % 10);
}
function pagosClabeOk(clabe) {
const limpia = String(clabe || '').replace(/[\s-]/g, '');
return /^\d{18}$/.test(limpia) && pagosDigitoClabe(limpia) === limpia[17];
}
const pagosMoney = value => {
const num = Number(value) || 0;
return num.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
const pagosCentsText = cents => pagosMoney((Number(cents) || 0) / 100);
function pagosCell(value) {
const td = n('td', String(value ?? ''), 'pagos-cell');
td.title = 'Clic para copiar este dato tal cual';
td.onclick = () => {
const texto = td.textContent;
const done = () => toast('Copiado: ' + texto, 'ok');
if (navigator.clipboard?.writeText) navigator.clipboard.writeText(texto).then(done).catch(() => pagosSelectCell(td, done));
else pagosSelectCell(td, done);
};
return td;
}
function pagosSelectCell(td, done) {
const range = document.createRange();
range.selectNodeContents(td);
const sel = window.getSelection();
sel.removeAllRanges(); sel.addRange(range);
try { document.execCommand('copy'); done(); } catch { toast('Seleccionado: cópialo con Ctrl+C', 'ok'); }
}
function pagosCopyText(texto, aviso) {
const done = () => toast(aviso || ('Copiado: ' + texto), 'ok');
if (navigator.clipboard?.writeText) { navigator.clipboard.writeText(texto).then(done).catch(() => pagosCopyFallback(texto, done)); return; }
pagosCopyFallback(texto, done);
}
function pagosCopyFallback(texto, done) {
const area = n('textarea');
area.value = texto;
document.body.append(area);
area.select();
try { document.execCommand('copy'); done(); } catch { toast('No se pudo copiar solo: selecciona la tabla y cópiala con Ctrl+C', 'error'); }
area.remove();
}

const pagosPad2 = value => String(value).padStart(2, '0');
function pagosIsoFecha(fecha) {
return fecha.getFullYear() + '-' + pagosPad2(fecha.getMonth() + 1) + '-' + pagosPad2(fecha.getDate());
}
function pagosParseFecha(iso) {
const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
return match ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3])) : null;
}
function pagosFechaLarga(iso) {
const fecha = pagosParseFecha(iso);
if (!fecha) return '—';
const partes = {};
for (const parte of new Intl.DateTimeFormat('es-MX', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).formatToParts(fecha))
partes[parte.type] = parte.value;
return partes.weekday + ' ' + partes.day + ' de ' + partes.month + ' de ' + partes.year;
}
function pagosMesLargo(mes) {
const match = /^(\d{4})-(\d{2})$/.exec(String(mes || ''));
if (!match) return '';
return new Intl.DateTimeFormat('es-MX', { month: 'long', year: 'numeric' }).format(new Date(Number(match[1]), Number(match[2]) - 1, 1));
}
function pagosDefaults(mes) {
const match = /^(\d{4})-(\d{2})$/.exec(String(mes || ''));
const hoy = new Date();
const anio = match ? Number(match[1]) : hoy.getFullYear();
const numMes = match ? Number(match[2]) : hoy.getMonth() + 1;
const diaDiez = new Date(anio, numMes - 1, 10);
const hoySinHora = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate());
const cargo = diaDiez < hoySinHora ? hoySinHora : diaDiez;
const siguiente = new Date(cargo.getFullYear(), cargo.getMonth(), cargo.getDate() + 1);
return {
referencia: pagosPad2(numMes) + String(anio),
fechaCargo: pagosIsoFecha(cargo),
fechaAbono: pagosIsoFecha(siguiente),
fechaAplicacion: pagosIsoFecha(siguiente)
};
}
function pagosCuentaGuardada() {
try { return localStorage.getItem(PAGOS_CUENTA_KEY + '-' + scope) || ''; } catch { return ''; }
}



function pagosGuardarCuentaLocal(cuenta) {
const limpia = String(cuenta || '').replace(/[\s-]/g, '');
try {
if (limpia) localStorage.setItem(PAGOS_CUENTA_KEY + '-' + scope, limpia);
else localStorage.removeItem(PAGOS_CUENTA_KEY + '-' + scope);
} catch {  }
}
function pagosGuardarCuenta(cuenta) {
const limpia = String(cuenta || '').replace(/[\s-]/g, '');
pagosGuardarCuentaLocal(limpia);
if (limpia && typeof satToken !== 'undefined' && satToken && scope)
satApi('pagos/config', { rfc: scope, cuentaRetiro: limpia }).catch(() => {});
}
function pagosCuentaTexto(cuenta) {
const limpia = String(cuenta || '').replace(/[\s-]/g, '');
return limpia
? 'Cuenta de retiro: ····' + limpia.slice(-4) + ' — la de la vez pasada'
: 'Cuenta de retiro: aún no hay una guardada. Teclea la tuya y quedará recordada para la próxima vez.';
}
const pagosScroll = el => { try { el?.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch {  } };

function pagosMakeStep(num, titulo) {
const section = n('section', undefined, 'panel step');
const head = n('div', undefined, 'step-head');
head.append(n('span', String(num), 'step-num'), n('h2', titulo));
const note = n('span', '', 'muted');
head.append(note);
const body = n('div', undefined, 'step-body');
section.append(head, body);
pagosSteps[num] = { section, body, note };
return pagosSteps[num];
}
function pagosRevealStep(num, nota) {
const step = pagosSteps[num];
if (!step) return;
step.body.hidden = false;
if (nota !== undefined) step.note.textContent = nota;
}
function pagosScreen() {
const wrap = n('div');
if (!pagosMes) {
const hoy = new Date();
pagosMes = hoy.getFullYear() + '-' + String(hoy.getMonth() + 1).padStart(2, '0');
}
const intro = panel('Pagos al banco',
'Tu base de beneficiarios y el generador de la lista de pagos: PacoSAT cruza las facturas del mes con la base y te entrega las tablas tal como las pide el banco, para copiar y pegar. Firmar y autorizar sigue siendo tuyo, en la página del banco.');
wrap.append(intro);
if (!satToken) {
intro.append(n('p', 'El catálogo y el generador viven en el servidor de tu casa (el NAS): abre PacoSAT desde el servidor para usarlos.', 'empty'));
return [wrap];
}
if (!scope) {
intro.append(n('p', 'Elige arriba el contribuyente (RFC) del que quieres preparar pagos.', 'empty'));
return [wrap];
}
pagosSteps = {};






const vencPanel = panel('Impuestos y cuotas por pagar',
'Lo que consta por pagar de este RFC, sacado de tus propias líneas ya preparadas y cruzado contra el banco para no pagar dos veces lo mismo.');
const vencBody = n('div');
vencPanel.append(vencBody);
wrap.append(vencPanel);
pagosFillVencimientos(vencBody, () => { if (typeof render === 'function') render(); });
const steps = n('div', undefined, 'steps');
wrap.append(steps);
const step1 = pagosMakeStep(1, 'A quién le pagas');
step1.note.textContent = 'Tu catálogo: normalmente solo se mira';
step1.body.append(n('p', 'Proveedores y clientes con su banco y su cuenta o CLABE. Al guardar, PacoSAT comprueba la CLABE dígito a dígito: un número mal copiado se caza aquí, no en el banco.', 'muted'));
const catBody = n('div');
step1.body.append(catBody);
steps.append(step1.section);
const step2 = pagosMakeStep(2, 'La lista del mes');
step2.note.textContent = 'Se abre cuando tu catálogo esté listo';
step2.body.hidden = pagosCatalogo === null;
const prepBody = n('div');
step2.body.append(prepBody);
steps.append(step2.section);
const step3 = pagosMakeStep(3, 'Las tablas para el banco');
step3.note.textContent = 'Se abre al armar la lista del mes';
step3.body.hidden = !pagosLineas.length;
step3.body.append(n('p', 'Un clic en una celda copia ese dato solo, entero, listo para pegarlo en su campo del banco. Con «Copiar la tabla» te llevas la tabla entera de un grupo. Al final tienes también el archivo de texto y el JSON (ese último es el que leerá el navegador del NAS).', 'muted'));
const genBtn = n('button', 'Generar las tablas', 'primary');
genBtn.disabled = !pagosLineas.length;
pagosGenBtn = genBtn;
genBtn.onclick = () => pagosGenerarTablas();
step3.body.append(genBtn);
const outBody = n('div');
step3.body.append(outBody);
steps.append(step3.section);
pagosCatBody = catBody;
pagosPrepBodyRef = prepBody;
pagosOutBody = outBody;
pagosFillCatalog(catBody, prepBody, outBody);
pagosFillPrepare(prepBody, outBody);
pagosFillOutput(outBody);



const historyPanel = panel('Preparaciones anteriores',
'Las listas que ya armaste quedan guardadas: reabre una para volver a ver sus tablas tal como salieron, o marca que ya la pagaste en el banco y sus facturas quedarán saldadas en Dinero.');
const histBody = n('div');
historyPanel.append(histBody);
wrap.append(historyPanel);
pagosFillHistory(histBody, outBody);
return [wrap];
}



async function pagosFillVencimientos(body, refrescar) {
body.replaceChildren(n('p', 'Revisando tus vencimientos y cruzándolos con el banco…', 'muted'));
let data = null;
try { data = await satApi('pagos/vencimientos?rfc=' + encodeURIComponent(scope)); }
catch (error) { if (body.isConnected) body.replaceChildren(n('p', error.message, 'error-text')); return; }
if (!body.isConnected) return;
body.replaceChildren();
const dinero = cents => '$' + (typeof centsLabel === 'function' ? centsLabel(BigInt(cents || 0)) : String(cents || 0));
if (data.todoPagado) {
const ok = n('div', undefined, 'pagos-todo-pagado');
ok.append(n('strong', '✓ Todo pagado'),
n('p', 'No consta ningún vencimiento de impuestos o cuotas por pagar de este RFC: ni líneas pendientes, ni meses declarados sin su línea. Cuando aparezca uno, aquí saldrá con su importe y su documento.'));
body.append(ok);
} else {
const bar = n('div', undefined, 'traffic-strip');
bar.append(statusPill('warn', number.format((data.vencimientos || []).length) + ' vencimiento(s) · ' + dinero(data.totalCents)));
body.append(bar);
}
for (const v of data.vencimientos || []) {
const row = n('div', undefined, 'cp-row');
row.append(statusPill(v.caducada ? 'bad' : 'warn', v.organismo));
const main = n('div', undefined, 'cp-main');
main.append(n('span', v.concepto + ' — ' + dinero(v.importeCents)));
main.append(n('small', 'Respaldo: ' + (v.respaldo?.label || 'su preparación') +
(v.lineaCaptura ? ' · Línea de captura ' + v.lineaCaptura : ''), 'muted'));
if (v.caducada) main.append(n('small', '⚠ ' + v.avisoCaducidad, 'error-text'));
else if (v.avisoCaducidad) main.append(n('small', '⚠ ' + v.avisoCaducidad, 'muted'));
row.append(main);
body.append(row);
}
for (const c of data.cruces || [])
body.append(n('p', 'Ya consta pagado (no se prepara otra vez): ' + c.concepto + ' — ' + c.motivo + '.', 'muted'));
if ((data.faltantes || []).length) {
const meses = data.faltantes.map(f => f.periodo).filter(Boolean);
body.append(n('p', '⚠ Sin importe que conste: ' +
(meses.length === 1 ? 'el mes ' + meses[0] : 'los meses ' + meses.join(', ')) +
' no constan presentados con acuse verificado ni tienen línea respaldada en el expediente — cuánto se debe no consta, y por eso esto no se puede preparar.', 'error-text'));
}
if ((data.vencimientos || []).length) {
const preparar = n('button', 'Preparar pagos', 'primary');
preparar.type = 'button';
preparar.onclick = async () => {
preparar.disabled = true; preparar.textContent = 'Preparando…';
try {
const creada = await satApi('pagos/preparar-vencimientos', { rfc: scope });
toast('Pagos preparados: la lista quedó en «Preparaciones anteriores» (' + creada.id + '), lista para autorizar en el banco. No se ha pagado nada.', 'ok');
refrescar();
} catch (error) { toast(error.message, 'error'); preparar.disabled = false; preparar.textContent = 'Preparar pagos'; }
};
body.append(n('p', 'Preparar junta los vencimientos en una sola lista del banco con su documento por concepto. Pagar sigue siendo tu gesto en el banco: aquí nada se paga solo.', 'muted'), preparar);
}
}
async function pagosFillHistory(histBody, outBody) {
histBody.replaceChildren(n('p', 'Cargando tus preparaciones…', 'muted'));
try {
const data = await satApi('pagos/preparations?rfc=' + encodeURIComponent(scope));
const lista = data.preparations || [];
histBody.replaceChildren();
if (!lista.length) {
histBody.append(n('p', 'Todavía no hay preparaciones guardadas: la primera nacerá al generar unas tablas en el paso 3.', 'muted'));
return;
}
for (const item of lista) {
const row = n('div', undefined, 'cp-row');
row.append(n('strong', pagosMesLargo(item.month)),
n('span', 'Armada el ' + localDateTime(item.created) + ' · ' + item.operaciones + ' operaciones · $' + pagosCentsText(item.totalCents), 'muted'));
if (item.pagadaEn) row.append(statusPill('ok', 'Pagada en el banco · ' + localDate(item.pagadaEn)));
const acts = n('div', undefined, 'actions');
acts.append(action('Reabrir', async () => {
const detalle = await satApi('pagos/preparation?rfc=' + encodeURIComponent(scope) + '&id=' + encodeURIComponent(item.id));
pagosPrep = detalle.preparation;
pagosTxt = detalle.txt || '';
pagosRevealStep(3, 'Preparación reabierta de ' + pagosMesLargo(item.month));
pagosFillOutput(outBody);

const lineas = [...(pagosPrep.bbva?.lines || []), ...(pagosPrep.interbancario?.lines || []), ...(pagosPrep.speiIndividual?.lines || [])];
const enlaces = lineas.filter(linea => linea.uuid);
if (enlaces.length) {
const linksBox = n('div');
linksBox.append(n('h3', 'Las facturas de esta preparación'));
for (const linea of enlaces) {
const factura = invoices.find(inv => inv.id === linea.uuid);
const lineaRow = n('div', undefined, 'cp-row');
lineaRow.append(n('span', (linea.folio ? 'Folio ' + linea.folio + ' · ' : '') + linea.nombre + ' · $' + pagosCentsText(linea.totalCents)));
if (factura) lineaRow.append(action('Ver la factura', () => invoiceDetail(factura), 'soft'));
linksBox.append(lineaRow);
}
outBody.append(linksBox);
}
pagosScroll(pagosSteps[3]?.section);
}, 'soft'));
if (!item.pagadaEn) acts.append(action('Ya pagué esto en el banco', async () => {
const resultado = await satApi('pagos/preparations/paid', { rfc: scope, id: item.id });
toast('Preparación sellada como pagada: ' + resultado.marcadas + ' factura(s) marcadas como pagadas en Dinero' +
(resultado.yaEstaban ? ' · ' + resultado.yaEstaban + ' ya constaban pagadas' : '') + '.', 'ok');
pagosFillHistory(histBody, outBody);
}, 'primary'));
row.append(acts);
histBody.append(row);
}
} catch (error) {
histBody.replaceChildren(n('p', error.message, 'error-text'));
}
}
async function pagosFillCatalog(catBody, prepBody, outBody) {
catBody.replaceChildren(n('p', 'Cargando tu catálogo…', 'muted'));
try {
const data = await satApi('pagos/catalog?rfc=' + encodeURIComponent(scope));
pagosCatalogo = data.beneficiaries || [];
} catch (error) {
catBody.replaceChildren(n('p', error.message, 'error-text'));
return;
}
pagosRevealStep(2, 'Listo: sigue con la lista del mes');
if (pagosSteps[1]) pagosSteps[1].note.textContent = pagosCatalogo.length
? pagosCatalogo.length + (pagosCatalogo.length === 1 ? ' beneficiario' : ' beneficiarios') + ' en el catálogo'
: 'Tu catálogo: normalmente solo se mira';
catBody.replaceChildren();
if (scope === 'MFI6212158B4' && !pagosCatalogo.length) {
const seedBox = n('div', undefined, 'pagos-seed');
seedBox.append(n('p', 'Tu catálogo está vacío. Para Mano Fil ya tienes verificados a García Rivera, Brisbane, Aceros y BG (cuentas y CLABE comprobadas el 9 de noviembre de 2026): cárgalos de un clic y edítalos cuando quieras.', 'muted'));
const seed = n('button', 'Cargar los beneficiarios verificados de Mano Fil', 'primary small');
seed.onclick = async () => {
seed.disabled = true;
try {
const data = await satApi('pagos/catalog', { rfc: scope, action: 'seed' });
pagosCatalogo = data.beneficiaries || [];
toast('Catálogo cargado con ' + (data.inserted || 0) + ' beneficiarios verificados.', 'ok');
pagosFillCatalog(catBody, prepBody, outBody);
} catch (error) { toast(error.message, 'error'); seed.disabled = false; }
};
seedBox.append(seed);
catBody.append(seedBox);
}
if (pagosCatalogo.length) {
const tableWrap = n('div', undefined, 'table-wrap');
const table = n('table', undefined, 'visor-table');
const thead = n('thead');
const hrow = n('tr');
for (const label of ['Beneficiario', 'RFC', 'Banco', 'Cuenta / CLABE', 'Grupo', 'Concepto habitual', 'Importe', '']) hrow.append(n('th', label));
thead.append(hrow);
table.append(thead);
const tbody = n('tbody');
for (const b of pagosCatalogo) {
const tr = n('tr');


const cuentaCell = n('td');
const numeroReal = b.clabe || b.cuenta || '';
const mascara = numeroReal ? '····' + numeroReal.slice(b.clabe ? -6 : -4) : '—';
const cuentaTxt = n('span', mascara);
cuentaCell.append(cuentaTxt);
if (numeroReal) {
const ver = n('button', 'Ver', 'soft small');
ver.onclick = () => {
const viendo = cuentaTxt.textContent === numeroReal;
cuentaTxt.textContent = viendo ? mascara : numeroReal;
ver.textContent = viendo ? 'Ver' : 'Ocultar';
};
cuentaCell.append(' ', ver);
}
tr.append(n('td', b.nombre), n('td', b.contraparte), n('td', b.banco || '—'),
cuentaCell, n('td', b.grupo),
n('td', b.concepto || '—'),
n('td', b.montoTipo === 'fijo' ? 'Fijo: $' + pagosMoney(b.base) + ' + IVA, ' + b.periodicidad : 'Variable, sale de cada factura'));
const actions = n('td');
const edit = n('button', 'Editar', 'soft small');
edit.onclick = () => { pagosEditando = b.id; pagosAltaPrefill = null; pagosFillCatalog(catBody, prepBody, outBody); };
const del = n('button', 'Borrar', 'soft small');


del.onclick = () => dialog('Borrar del catálogo',
[n('p', '¿Borrar a «' + b.nombre + '» del catálogo? Sus facturas ya no se cruzarán solas al armar la lista.')],
async () => {
const data = await satApi('pagos/catalog', { rfc: scope, action: 'delete', id: b.id });
pagosCatalogo = data.beneficiaries || [];
toast('Beneficiario borrado del catálogo.', 'ok');
pagosFillCatalog(catBody, prepBody, outBody);
}, 'Borrar');
actions.append(edit, del);
tr.append(actions);
tbody.append(tr);
}
table.append(tbody);
tableWrap.append(table);
catBody.append(tableWrap);
} else if (scope !== 'MFI6212158B4') {
catBody.append(empty('Tu catálogo está vacío',
'Da de alta tu primer beneficiario con el formulario de abajo: la CLABE se comprueba al guardar.'));
}
catBody.append(pagosForm(catBody, prepBody, outBody));
if (pagosAltaPrefill && pagosNombreInput) {
pagosScroll(pagosSteps[1]?.section);
try { pagosNombreInput.focus(); } catch {  }
}
}
function pagosForm(catBody, prepBody, outBody) {
const editing = pagosCatalogo?.find(b => b.id === pagosEditando) || null;
const prefill = !editing && pagosAltaPrefill ? pagosAltaPrefill : null;
const box = n('div', undefined, 'pagos-form');
box.append(n('h3', editing ? 'Editar beneficiario' : 'Dar de alta un beneficiario'));
if (prefill) box.append(n('p', 'Viene de una factura del mes sin beneficiario: ya trae su nombre y su RFC; completa su banco y su cuenta o CLABE.', 'muted'));
const grid = n('div', undefined, 'pagos-grid');
const field = (label, control) => {
const cell = n('label', undefined, 'pagos-field');
cell.append(n('span', label), control);
grid.append(cell);
return control;
};
const tipo = field('Tipo', select([['proveedor', 'Proveedor (le pago)'], ['cliente', 'Cliente (me paga)']], editing?.tipo || 'proveedor', 'Tipo'));
const nombre = field('Razón social', input('text', { value: editing?.nombre || prefill?.nombre || '', placeholder: 'Como viene en su factura' }));
pagosNombreInput = nombre;
const contraparte = field('Su RFC', input('text', { value: editing?.contraparte || prefill?.contraparte || '', placeholder: 'Ej. ABC010101XY2' }));
const banco = field('Banco', input('text', { value: editing?.banco || '', placeholder: 'Se deduce de la CLABE si lo dejas vacío' }));
const cuenta = field('Cuenta BBVA (10 dígitos)', input('text', { value: editing?.cuenta || '', inputmode: 'numeric', placeholder: 'Solo si cobra en BBVA' }));
const clabe = field('CLABE (18 dígitos)', input('text', { value: editing?.clabe || '', inputmode: 'numeric', placeholder: 'Para cualquier banco' }));
const grupo = field('Grupo del banco', select([['', 'Automático (cuenta → BBVA, CLABE → Interbancario)'], ['BBVA', 'Grupo BBVA'], ['Interbancario', 'Grupo Interbancario']], editing?.grupo || '', 'Grupo'));
const concepto = field('Concepto / motivo habitual', input('text', { value: editing?.concepto || '', placeholder: 'Ej. SERVICIO DE COBRANZA' }));
const montoTipo = field('El importe es', select([['variable', 'Variable: sale de cada factura'], ['fijo', 'Fijo: se repite cada periodo']], editing?.montoTipo || 'variable', 'Tipo de importe'));
const base = field('Importe base (sin IVA, si es fijo)', input('text', { value: editing?.base || '', inputmode: 'decimal', placeholder: '0.00' }));
const iva = field('IVA (si es fijo; vacío = 16% de la base)', input('text', { value: editing?.iva || '', inputmode: 'decimal', placeholder: 'Automático' }));
const periodicidad = field('Periodicidad del fijo', select([['mensual', 'Cada mes'], ['quincenal', 'Cada quincena'], ['unico', 'Una sola vez']], editing?.periodicidad || 'mensual', 'Periodicidad'));



const celdasFijo = [base, iva, periodicidad].map(control => control.closest('label'));
const pintaFijo = () => { for (const celda of celdasFijo) if (celda) celda.hidden = montoTipo.value !== 'fijo'; };
montoTipo.onchange = pintaFijo;
pintaFijo();
box.append(grid);
const aviso = n('p', '', 'muted');
clabe.oninput = () => {
const value = clabe.value.replace(/[\s-]/g, '');
aviso.textContent = !value ? '' : value.length !== 18 ? 'La CLABE lleva 18 dígitos (van ' + value.length + ').'
: pagosClabeOk(value) ? '✓ CLABE válida: su dígito de control cuadra.' : '✗ El dígito de control no cuadra: revisa el número.';
};
box.append(aviso);
const row = n('div', undefined, 'pagos-actions');
const save = n('button', editing ? 'Guardar los cambios' : 'Guardar en el catálogo', 'primary small');
save.onclick = async () => {
const beneficiary = {
id: editing?.id || '', tipo: tipo.value, nombre: nombre.value.trim(),
contraparte: contraparte.value.trim().toUpperCase(), banco: banco.value.trim(),
cuenta: cuenta.value.trim(), clabe: clabe.value.trim(), grupo: grupo.value,
concepto: concepto.value.trim(), montoTipo: montoTipo.value,
base: base.value.trim(), iva: iva.value.trim(), periodicidad: periodicidad.value
};
if (beneficiary.clabe && !pagosClabeOk(beneficiary.clabe)) {
toast('Esa CLABE no pasa su dígito de control: no la guardo, podría mandar el dinero a otra cuenta.', 'error');
return;
}
save.disabled = true;
try {
const data = await satApi('pagos/catalog', { rfc: scope, action: 'save', beneficiary });
pagosCatalogo = data.beneficiaries || [];
pagosEditando = '';
pagosAltaPrefill = null;
toast('Beneficiario guardado y verificado en el catálogo.', 'ok');
pagosFillCatalog(catBody, prepBody, outBody);
} catch (error) { toast(error.message, 'error'); save.disabled = false; }
};
row.append(save);
if (editing) {
const cancel = n('button', 'Cancelar la edición', 'soft small');
cancel.onclick = () => { pagosEditando = ''; pagosFillCatalog(catBody, prepBody, outBody); };
row.append(cancel);
}
if (prefill) {
const cancel = n('button', 'Cancelar el alta', 'soft small');
cancel.onclick = () => { pagosAltaPrefill = null; pagosFillCatalog(catBody, prepBody, outBody); };
row.append(cancel);
}
box.append(row);
return box;
}
function pagosFillPrepare(prepBody, outBody) {
prepBody.replaceChildren();
prepBody.append(n('p', 'La lista sale de las facturas recibidas del mes que ya están verificadas en Facturas, casadas con tu catálogo por el RFC del emisor, más tus pagos fijos. Todo viene ya relleno con tu rutina: revisa, ajusta lo que sea y arma la lista.', 'muted'));
const defaults = pagosDefaults(pagosMes);
const tocados = { referencia: false, fechaAbono: false, fechaAplicacion: false };
const controls = n('div', undefined, 'pagos-grid');
const field = (label, control, nota) => {
const cell = n('label', undefined, 'pagos-field');
cell.append(n('span', label), control);
if (nota) cell.append(nota);
controls.append(cell);
return control;
};
const mesNota = n('p', pagosMesLargo(pagosMes), 'muted');
const mes = field('Mes a pagar', input('month', { value: pagosMes }), mesNota);
const descripcion = field('Descripción del grupo', input('text', { value: 'PROVEEDORES' }));
const cuentaDato = n('p', pagosCuentaTexto(pagosCuentaGuardada()), 'muted');
const cuentaRetiro = field('Cuenta de retiro (la tuya, de donde sale)', input('text', { value: pagosCuentaGuardada(), inputmode: 'numeric', placeholder: '10 dígitos' }), cuentaDato);
cuentaRetiro.onchange = () => {
pagosGuardarCuenta(cuentaRetiro.value);
cuentaDato.textContent = pagosCuentaTexto(cuentaRetiro.value);
};
const referencia = field('Referencia numérica (interbancario)', input('text', { value: defaults.referencia, inputmode: 'numeric', placeholder: 'Ej. 112026' }));
referencia.oninput = () => { tocados.referencia = true; };
const fechaNota = iso => n('p', pagosFechaLarga(iso), 'muted');
const cargoNota = fechaNota(defaults.fechaCargo);
const fechaCargo = field('Fecha de cargo (interbancario)', input('date', { value: defaults.fechaCargo }), cargoNota);
const abonoNota = fechaNota(defaults.fechaAbono);
const fechaAbono = field('Fecha de abono (interbancario)', input('date', { value: defaults.fechaAbono }), abonoNota);
fechaAbono.onchange = () => { tocados.fechaAbono = true; abonoNota.textContent = pagosFechaLarga(fechaAbono.value); };
const aplicNota = fechaNota(defaults.fechaAplicacion);
const fechaAplicacion = field('Fecha de aplicación (grupo BBVA)', input('date', { value: defaults.fechaAplicacion }), aplicNota);
fechaAplicacion.onchange = () => { tocados.fechaAplicacion = true; aplicNota.textContent = pagosFechaLarga(fechaAplicacion.value); };
fechaCargo.onchange = () => {
cargoNota.textContent = pagosFechaLarga(fechaCargo.value);
const cargo = pagosParseFecha(fechaCargo.value);
if (!cargo) return;
const siguiente = pagosIsoFecha(new Date(cargo.getFullYear(), cargo.getMonth(), cargo.getDate() + 1));
if (!tocados.fechaAbono) { fechaAbono.value = siguiente; abonoNota.textContent = pagosFechaLarga(siguiente); }
if (!tocados.fechaAplicacion) { fechaAplicacion.value = siguiente; aplicNota.textContent = pagosFechaLarga(siguiente); }
};
mes.onchange = () => {
pagosMes = mes.value;
mesNota.textContent = pagosMesLargo(pagosMes);
const nuevos = pagosDefaults(pagosMes);
if (!tocados.referencia) referencia.value = nuevos.referencia;
fechaCargo.value = nuevos.fechaCargo;
cargoNota.textContent = pagosFechaLarga(nuevos.fechaCargo);
if (!tocados.fechaAbono) { fechaAbono.value = nuevos.fechaAbono; abonoNota.textContent = pagosFechaLarga(nuevos.fechaAbono); }
if (!tocados.fechaAplicacion) { fechaAplicacion.value = nuevos.fechaAplicacion; aplicNota.textContent = pagosFechaLarga(nuevos.fechaAplicacion); }
};
prepBody.append(controls);
pagosGroupInputs = { descripcion, cuentaRetiro, referencia, fechaCargo, fechaAbono, fechaAplicacion };


satApi('pagos/config?rfc=' + encodeURIComponent(scope)).then(data => {
if (data?.cuentaRetiro) {
cuentaRetiro.value = data.cuentaRetiro;
cuentaDato.textContent = pagosCuentaTexto(data.cuentaRetiro);
pagosGuardarCuentaLocal(data.cuentaRetiro);
}
}).catch(() => {});
const armar = n('button', 'Armar la lista desde las facturas del mes', 'primary');
const linesBox = n('div');
armar.onclick = async () => {
armar.disabled = true;
try {
const data = await satApi('pagos/proposal?rfc=' + encodeURIComponent(scope) + '&month=' + encodeURIComponent(pagosMes));
pagosLineas = (data.lines || []).map(linea => ({ ...linea, incluir: true }));
pagosSinCatalogo = data.sinCatalogo || [];
pagosPrep = null;
pagosTxt = '';
pagosFillOutput(outBody);
toast(pagosLineas.length ? 'Lista armada con ' + pagosLineas.length + ' líneas: revísalas una a una antes de generar.'
: 'Sin líneas para ese mes: revisa que las facturas estén en Facturas y sus emisores en el catálogo.', pagosLineas.length ? 'ok' : 'error');
pagosFillLines(linesBox, pagosGroupInputs, outBody);
} catch (error) { toast(error.message, 'error'); }
finally { armar.disabled = false; }
};
prepBody.append(armar, linesBox);
if (pagosLineas.length) pagosFillLines(linesBox, pagosGroupInputs, outBody);
}
function pagosFillLines(linesBox, groupInputs, outBody) {
linesBox.replaceChildren();
if (pagosSinCatalogo.length) {
const warn = n('div', undefined, 'pagos-warn');
warn.append(n('strong', 'Facturas del mes sin beneficiario en el catálogo (no entran en la lista):'));
for (const item of pagosSinCatalogo) {
const row = n('div', undefined, 'pagos-actions');
row.append(n('p', '· ' + (item.emisorNombre || item.emisorRfc) + ' (' + item.emisorRfc + ') — folio ' +
(item.folio || 's/f') + ' por $' + pagosMoney(item.total) + '. Da de alta al beneficiario y vuelve a armar la lista.', 'muted'));
const alta = n('button', 'Dar de alta', 'soft small');
alta.onclick = () => {
pagosEditando = '';
pagosAltaPrefill = { nombre: item.emisorNombre || '', contraparte: item.emisorRfc || '' };
if (pagosCatBody) pagosFillCatalog(pagosCatBody, pagosPrepBodyRef, outBody);
};
row.append(alta);
warn.append(row);
}
linesBox.append(warn);
}
if (!pagosLineas.length) {
linesBox.append(n('p', 'Aún no hay lista: pulsa «Armar la lista desde las facturas del mes».', 'muted'));
if (pagosGenBtn) pagosGenBtn.disabled = true;
return;
}
const tableWrap = n('div', undefined, 'table-wrap');
const table = n('table', undefined, 'visor-table pagos-lines');
const thead = n('thead');
const hrow = n('tr');
for (const label of ['Pagar', 'Beneficiario', 'Cuenta / CLABE', 'Importe', 'Motivo de pago', 'RFC', 'IVA']) hrow.append(n('th', label));
thead.append(hrow);
table.append(thead);
const tbody = n('tbody');
pagosLineas.forEach((linea, idx) => {
const tr = n('tr');
const check = input('checkbox', { checked: linea.incluir !== false });
check.onchange = () => { linea.incluir = check.checked; };
const checkCell = n('td'); checkCell.append(check); tr.append(checkCell);
tr.append(n('td', linea.nombre + (linea.fijo ? ' · pago fijo' : linea.folio ? ' · factura ' + linea.folio : '')));
tr.append(n('td', linea.grupo === 'BBVA' ? linea.cuenta : linea.clabe));
const importe = input('text', { value: linea.total, inputmode: 'decimal', 'aria-label': 'Importe' });
importe.onchange = () => { linea.total = importe.value; };
const importeCell = n('td'); importeCell.append(importe); tr.append(importeCell);
const motivo = input('text', { value: linea.motivo || '', 'aria-label': 'Motivo de pago' });
motivo.onchange = () => { linea.motivo = motivo.value; };
const motivoCell = n('td'); motivoCell.append(motivo); tr.append(motivoCell);
tr.append(n('td', linea.rfc || ''));
const iva = input('text', { value: linea.iva, inputmode: 'decimal', 'aria-label': 'IVA' });
iva.onchange = () => { linea.iva = iva.value; };
const ivaCell = n('td'); ivaCell.append(iva); tr.append(ivaCell);
tbody.append(tr);
});
table.append(tbody);
tableWrap.append(table);
linesBox.append(tableWrap);
linesBox.append(n('p', 'Así la verá el banco. Deja marcada la casilla «Pagar» en lo que sí va este mes y sigue al paso 3 para generar las tablas.', 'muted'));
if (pagosGenBtn) pagosGenBtn.disabled = false;
pagosRevealStep(3, 'Lista armada: ya puedes generar las tablas');
pagosScroll(pagosSteps[3]?.section);
}
async function pagosGenerarTablas() {
const groupInputs = pagosGroupInputs;
const outBody = pagosOutBody;
if (!groupInputs || !outBody) return;
const lines = pagosLineas.filter(linea => linea.incluir !== false).map(linea => ({
beneficiaryId: linea.beneficiaryId || '', nombre: linea.nombre, rfc: linea.rfc, banco: linea.banco,
grupo: linea.grupo, cuenta: linea.cuenta, clabe: linea.clabe, motivo: linea.motivo,
folio: linea.folio, uuid: linea.uuid, fijo: linea.fijo, base: linea.base, iva: linea.iva, total: linea.total
}));
if (!lines.length) { toast('Marca al menos una línea para pagar.', 'error'); return; }
if (pagosGenBtn) pagosGenBtn.disabled = true;
try {
const data = await satApi('pagos/prepare', { rfc: scope, month: pagosMes, lines,
group: { descripcion: groupInputs.descripcion.value, cuentaRetiro: groupInputs.cuentaRetiro.value,
referencia: groupInputs.referencia.value, fechaCargo: groupInputs.fechaCargo.value,
fechaAbono: groupInputs.fechaAbono.value, fechaAplicacion: groupInputs.fechaAplicacion.value } });
pagosPrep = data.preparation;
pagosTxt = data.txt || '';
pagosGuardarCuenta(groupInputs.cuentaRetiro.value);
toast('Tablas generadas: ' + pagosPrep.operaciones + ' operaciones por $' + pagosCentsText(pagosPrep.totalCents) + '.', 'ok');
pagosRevealStep(3, 'Tablas generadas');
pagosFillOutput(outBody);
pagosScroll(pagosSteps[3]?.section);
} catch (error) { toast(error.message, 'error'); }
finally { if (pagosGenBtn) pagosGenBtn.disabled = false; }
}
function pagosOutputTable(headers, rows, overFlags) {
const tableWrap = n('div', undefined, 'table-wrap');
const table = n('table', undefined, 'visor-table pagos-table');
const thead = n('thead');
const hrow = n('tr');
for (const label of headers) hrow.append(n('th', label));
thead.append(hrow);
table.append(thead);
const tbody = n('tbody');
rows.forEach((cells, i) => {
const tr = n('tr');
if (overFlags?.[i]) tr.className = 'pagos-over';
for (const value of cells) tr.append(pagosCell(value));
tbody.append(tr);
});
table.append(tbody);
tableWrap.append(table);
return tableWrap;
}
function pagosCopyTableBtn(headers, rows) {
const btn = n('button', 'Copiar la tabla', 'soft small');
btn.onclick = () => pagosCopyText([headers.join('\t'), ...rows.map(cells => cells.join('\t'))].join('\n'), 'Tabla copiada entera: pégala donde la necesites.');
return btn;
}
function pagosGroupCard(titulo, nota, headers, rows, control, overFlags, cls) {
const card = n('div', undefined, cls || 'kpi');
card.append(n('strong', titulo));
if (nota) card.append(n('small', nota));
card.append(pagosOutputTable(headers, rows, overFlags));
if (control) card.append(n('p', control, 'muted'));
const actions = n('div', undefined, 'pagos-actions');
actions.append(pagosCopyTableBtn(headers, rows));
card.append(actions);
return card;
}
function pagosFillOutput(outBody) {
outBody.replaceChildren();
if (!pagosPrep) {
outBody.append(n('p', 'Todavía no hay tablas: arma la lista en el paso 2 y pulsa «Generar las tablas».', 'muted'));
return;
}
const prep = pagosPrep;
const hero = n('div', undefined, 'total-hero kpi');
hero.append(n('strong', 'Total a pagar: $' + pagosCentsText(prep.totalCents)));
hero.append(n('small', 'en ' + prep.operaciones + (prep.operaciones === 1 ? ' operación' : ' operaciones') + ' · ' + pagosMesLargo(prep.month || pagosMes)));
outBody.append(hero);
const cards = n('div', undefined, 'kpis');
if (prep.bbva.lines.length) {
const rows = prep.bbva.lines.map(linea => [linea.cuenta, pagosCentsText(linea.totalCents).replace(/,/g, '')]);
cards.append(pagosGroupCard(
'Grupo BBVA — ' + prep.bbva.operaciones + (prep.bbva.operaciones === 1 ? ' operación' : ' operaciones') + ' · $' + pagosCentsText(prep.bbva.totalCents),
'«' + prep.group.descripcion + '» · Aplicación: ' + pagosFechaLarga(prep.group.fechaAplicacion),
['Cuenta', 'Importe'], rows,
'Control del banco: ' + prep.bbva.operaciones + ' operaciones · importe de cargo $' +
pagosCentsText(prep.bbva.totalCents) + '. El titular que debe salir al validar es el de cada beneficiario.'));
}
if (prep.interbancario.lines.length) {
const rows = prep.interbancario.lines.map(linea => [linea.nombre, linea.clabe, pagosCentsText(linea.totalCents).replace(/,/g, ''),
linea.motivo || linea.folio || '', linea.rfc, pagosCentsText(linea.ivaCents).replace(/,/g, '')]);
cards.append(pagosGroupCard(
'Grupo Interbancario — ' + prep.interbancario.operaciones + (prep.interbancario.operaciones === 1 ? ' operación' : ' operaciones') + ' · $' + pagosCentsText(prep.interbancario.totalCents),
'«' + prep.group.descripcion + '» · Cargo: ' + pagosFechaLarga(prep.group.fechaCargo) + ' · Abono: ' + pagosFechaLarga(prep.group.fechaAbono) +
(prep.group.referencia ? ' · Referencia ' + prep.group.referencia : ''),
['Nombre', 'Cuenta CLABE', 'Importe', 'Motivo de Pago', 'RFC', 'IVA'], rows,
'Control del banco: ' + prep.interbancario.operaciones + ' operaciones · importe de cargo $' +
pagosCentsText(prep.interbancario.totalCents) + '.'));
}
if (cards.childElementCount) outBody.append(cards);
if (prep.speiIndividual.lines.length) {
const rows = prep.speiIndividual.lines.map(linea => [linea.nombre, linea.clabe, pagosCentsText(linea.totalCents).replace(/,/g, ''),
linea.motivo || linea.folio || '', linea.rfc, pagosCentsText(linea.ivaCents).replace(/,/g, '')]);
const spei = pagosGroupCard(
'Por SPEI individual — ' + prep.speiIndividual.operaciones + (prep.speiIndividual.operaciones === 1 ? ' operación' : ' operaciones') + ' · $' + pagosCentsText(prep.speiIndividual.totalCents),
'', ['Nombre', 'Cuenta CLABE', 'Importe', 'Motivo de Pago', 'RFC', 'IVA'], rows,
'Total por SPEI individual: $' + pagosCentsText(prep.speiIndividual.totalCents) + '.',
prep.speiIndividual.lines.map(() => true), 'kpi warn pagos-warn');
const explicacion = n('p', 'Hay pagos que superan el tope de $' + pagosMoney(PAGOS_TOPE) +
' por operación que el banco pone a los grupos interbancarios. Esos no van en el grupo — el banco te lo echaría para atrás —: se pagan uno a uno por SPEI individual, desde Operaciones frecuentes. Por eso no cuentan en el total de ningún grupo, pero sí en el total del mes.', 'error-text');
spei.insertBefore(explicacion, spei.children[1] || null);
explicacion.after(...prep.speiIndividual.lines.map(linea =>
n('p', '· ' + linea.nombre + ' · $' + pagosCentsText(linea.totalCents) + ' — este va por SPEI individual', 'muted')));
outBody.append(spei);
}
const downloads = n('div', undefined, 'pagos-actions');
const txtBtn = n('button', 'Descargar el texto (.txt)', 'soft small');
txtBtn.onclick = () => download(new Blob([pagosTxt], { type: 'text/plain;charset=utf-8' }),
'pagos-' + scope + '-' + (prep.month || pagosMes) + '.txt');
const jsonBtn = n('button', 'Descargar el JSON (para el navegador del NAS)', 'soft small');
jsonBtn.onclick = () => download(new Blob([JSON.stringify(prep, null, 2)], { type: 'application/json;charset=utf-8' }),
'pagos-' + scope + '-' + (prep.month || pagosMes) + '.json');
downloads.append(txtBtn, jsonBtn);
outBody.append(downloads);
}

bancos.source:
const BANK_QUICK = [['BBVA', 'Cuenta Maestra Pyme', 'cuenta'], ['BBVA', 'Fondo', 'fondo'],
['Santander', 'Cuenta de cheques', 'cuenta'], ['Santander', 'FONSER1', 'fondo'], ['Konfio', 'Cuenta', 'cuenta']];
function bancosScreen() {
const wrap = n('div');
if (!satToken) {
const panelEl = panel('Bancos vive en tu servidor', 'Los estados de cuenta se archivan y se leen en el servidor de casa (el NAS), no en este navegador. Abre PacoSAT desde el servidor para usar esta pantalla.');
wrap.append(panelEl);
return [wrap];
}
const body = n('div');
wrap.append(body);
const draw = data => {
body.replaceChildren();

const position = panel('Posición total', 'La suma de los últimos saldos finales archivados, por banco y en total. Cada saldo enseña el mes de su estado: la suma nunca mezcla meses en silencio (1.28.0, P10).');
const strip = n('div', undefined, 'traffic-strip');
strip.append(statusPill('ok', 'Total: $' + data.position.total + (data.position.asOf ? ' · a ' + data.position.asOf : '')));
for (const [bank, total] of Object.entries(data.position.byBank))
strip.append(statusPill('dim', bank + ': $' + total));
position.append(strip);



const cuentas = data.position.cuentas || [];
if (cuentas.length) {
const meses = new Set(cuentas.map(cuenta => cuenta.mes));
for (const cuenta of cuentas)
position.append(n('p', cuenta.banco + (cuenta.nombre ? ' · ' + cuenta.nombre : '') +
': $' + cuenta.saldo + ' — saldo de ' + cuenta.mes + '.', 'today-line'));
if (meses.size > 1)
position.append(n('p', '⚠ Ojo: el total suma saldos de meses distintos (' + [...meses].sort().join(', ') +
'): cada cuenta aporta su último estado archivado. Sube el estado que falta y la posición queda de un solo mes.', 'today-line'));
}
body.append(position);
if (!data.accounts.length) {
const empty = panel('Tus cuentas', 'Da de alta la primera cuenta con un toque o con el formulario. Después sube el PDF de cada mes y PacoSAT lee los saldos.');
const chips = n('div', undefined, 'traffic-strip');
for (const [bank, name, kind] of BANK_QUICK) {
const chip = n('button', bank + ' · ' + name, 'soft small');
chip.onclick = async () => { await satApi('banks/accounts', { bank, name, kind }); announce('Cuenta creada.'); refresh(); };
chips.append(chip);
}
empty.append(chips);
body.append(empty);
}



for (const account of data.accounts) {
if (scope && account.rfc && account.rfc !== scope) continue;
body.append(bankAccountPanel(account, draw));
}
body.append(bankAccountForm(draw));
};
satApi('banks').then(draw).catch(error => { body.append(panel('Bancos', 'No se pudo cargar: ' + error.message)); });
return [wrap];
}
function bankAccountPanel(account, draw) {
const title = account.bank + ' · ' + account.name + (account.last4 ? ' ····' + account.last4 : '') +
(account.rfc ? ' · de ' + account.rfc : ' · sin RFC dueño');
const panelEl = panel(title, account.position ? 'Último saldo: $' + account.position.closing + ' (' + account.position.month + ').' : 'Aún sin estados archivados.');
const strip = n('div', undefined, 'traffic-strip');
strip.append(statusPill(account.missing.length ? 'warn' : 'ok',
account.missing.length ? 'Faltan ' + account.missing.length + ' meses: ' + account.missing.slice(0, 4).join(', ') + (account.missing.length > 4 ? '…' : '') : 'Sin meses faltantes'));
strip.append(statusPill(account.chainBroken ? 'bad' : 'ok', account.chainBroken ? 'Cadena de saldos ROTA (ver el mes marcado)' : 'Cadena de saldos continua'));
panelEl.append(strip);





const ownerForm = n('div', undefined, 'sat-form');
const ownerSel = select([['', 'Sin RFC dueño (se ve en todos)'],
...people.map(p => [p.id, (p.name || p.id) + ' · ' + p.id])], account.rfc || '', 'RFC dueño');
const assignBtn = n('button', 'Asignar dueño', 'soft small');
assignBtn.onclick = async () => {
try { const data = await satApi('banks/accounts', { id: account.id, rfc: ownerSel.value });
announce(ownerSel.value ? 'Cuenta asignada a ' + ownerSel.value + '.' : 'Cuenta sin RFC dueño: se ve en todos.'); draw(data); }
catch (error) { toast(error.message, 'error'); }
};
ownerForm.append(fieldWrap('RFC dueño de esta cuenta', ownerSel), assignBtn);
panelEl.append(ownerForm);
for (const statement of account.statements) {
const row = n('div', undefined, 'cp-row');
row.append(statusPill(statement.chain === 'broken' ? 'bad' : statement.state === 'ok' ? 'ok' : statement.state === 'manual' ? 'ok' : 'warn', statement.month),
n('span', (statement.detected ? statement.detected + ' · ' : '') + 'inicial ' + (statement.opening ?? '¿?') +
' → final ' + (statement.closing ?? '¿?') + ' · ' + statement.movements + ' movimientos' +
(statement.state === 'review' ? ' · A REVISAR: confirma los saldos' : statement.state === 'manual' ? ' · confirmado a mano' : '')));
if (statement.chainDetail) row.title = statement.chainDetail;
if (statement.state === 'review') {
const confirmBtn = n('button', 'Confirmar saldos', 'soft small');
confirmBtn.onclick = () => bankConfirmDialog(statement, draw);
row.append(confirmBtn);
}
const del = n('button', 'Quitar', 'soft small');


del.onclick = () => dialog('Quitar este estado de cuenta',
[n('p', 'Se elimina el estado de ' + statement.month + ' de esta cuenta, con su lectura de saldos y movimientos. La cuenta y los demás estados quedan como están.')],
async () => { await satApi('banks/statements/delete', { id: statement.id }); announce('Estado eliminado.'); refresh(); }, 'Quitar estado');
row.append(del);
panelEl.append(row);
if (statement.chainDetail) panelEl.append(n('p', '⚠ ' + statement.chainDetail, 'error-text'));
}

const form = n('div', undefined, 'sat-form');
const month = input('month', { value: previousMonthKey() });
const file = input('file', { accept: 'application/pdf' });
const upload = n('button', 'Subir y leer el estado', 'soft');
upload.onclick = async () => {
try {
check(file.files?.[0], 'Elige el PDF del estado de cuenta.');
check(/^\d{4}-\d{2}$/.test(month.value), 'Elige el mes del estado.');
const content = encode64(new Uint8Array(await file.files[0].arrayBuffer()));
const data = await satApi('banks/statements', { accountId: account.id, month: month.value, content });
announce('Estado archivado y leído. Revisa sus saldos en la lista.');
soundCue('success');
draw(data);
} catch (error) { toast(error.message, 'error'); }
};
form.append(fieldWrap('Mes del estado', month), fieldWrap('PDF', file), upload);
const delAccount = n('button', 'Eliminar esta cuenta y sus estados', 'soft');
delAccount.onclick = () => dialog('Eliminar esta cuenta y sus estados',
[n('p', 'Se elimina la cuenta completa con TODOS sus estados archivados y su conciliación. No hay deshacer: si solo sobra un estado, quítalo a él desde su fila.')],
async () => { await satApi('banks/accounts', { delete: account.id }); announce('Cuenta eliminada.'); refresh(); }, 'Eliminar cuenta');
panelEl.append(form, delAccount);
return panelEl;
}
function bankConfirmDialog(statement, draw) {
const form = n('form', undefined, 'dialog-form');
form.append(n('h3', 'Confirmar saldos · ' + statement.month),
n('p', 'La lectura automática no pudo asegurar estas cifras. Escríbelas tal como vienen en el estado: PacoSAT no inventa importes.', 'muted'));
const opening = input('text', { value: statement.opening || '', inputmode: 'decimal' });
const closing = input('text', { value: statement.closing || '', inputmode: 'decimal' });
const credits = input('text', { value: statement.credits || '', inputmode: 'decimal' });
const charges = input('text', { value: statement.charges || '', inputmode: 'decimal' });
form.append(fieldWrap('Saldo inicial', opening), fieldWrap('Saldo final', closing),
fieldWrap('Total de abonos (opcional)', credits), fieldWrap('Total de cargos (opcional)', charges));
const save = n('button', 'Guardar cifras confirmadas', 'primary');
save.type = 'submit';
form.onsubmit = async event => {
event.preventDefault();
try {
const data = await satApi('banks/statements/confirm', { id: statement.id, opening: opening.value, closing: closing.value, credits: credits.value, charges: charges.value });
closeDialog(); announce('Saldos confirmados.'); draw(data);
} catch (error) { toast(error.message, 'error'); }
};
const cancel = n('button', 'Cancelar', 'soft');
cancel.type = 'button';
cancel.onclick = closeDialog;
form.append(save, cancel);
showDialog(form);
}
function bankAccountForm(draw) {
const panelEl = panel('Añadir otra cuenta', 'Banco y nombre libres: sirve para cualquier banco, cuenta o fondo.');
const form = n('div', undefined, 'sat-form');
const bank = input('text', { placeholder: 'BBVA, Santander, Konfio…' });
const name = input('text', { placeholder: 'Cuenta principal, Fondo…' });
const last4 = input('text', { placeholder: 'Últimos 4 (opcional)', maxlength: '4' });


const owner = select([['', 'Sin RFC dueño (se ve en todos)'],
...people.map(p => [p.id, (p.name || p.id) + ' · ' + p.id])], scope || '', 'RFC dueño');
const add = n('button', 'Crear cuenta', 'soft');
add.onclick = async () => {
try { const data = await satApi('banks/accounts', { bank: bank.value, name: name.value, last4: last4.value, rfc: owner.value }); announce('Cuenta creada.'); draw(data); }
catch (error) { toast(error.message, 'error'); }
};
form.append(fieldWrap('Banco', bank), fieldWrap('Nombre', name), fieldWrap('Terminación', last4), fieldWrap('RFC dueño', owner), add);
panelEl.append(form);
return panelEl;
}

registro.source:
let registroFiltro = { rfc: '', clase: '' };
const REGISTRO_CLASE = { conexion: ['ok', 'Conexión'], accion: ['dim', 'Acción'], fallo: ['bad', 'Fallo'] };
function registroScreen() {
const wrap = n('div');
if (typeof satToken === 'undefined' || !satToken) {
wrap.append(panel('Registro', 'El Registro vive en el servidor de tu casa (el NAS): abre PacoSAT desde el servidor para ver qué hizo el sistema, qué intentó y qué no pudo.'));
return [wrap];
}
const head = panel('Registro',
'Todo lo que el sistema hizo, intentó y no pudo, en una sola lista y en lenguaje llano: conexiones con el SAT, acciones (tuyas y automáticas) y fallos con su motivo. Cuando un motor guardó la página del momento del fallo, el botón «Ver la página del fallo» la abre.');
const body = n('div');
head.append(body);
wrap.append(head);
const pintar = async () => {
body.replaceChildren(n('p', 'Leyendo el registro…', 'muted'));
let data = null;
try {
data = await satApi('registro?limit=300' +
(registroFiltro.rfc ? '&rfc=' + encodeURIComponent(registroFiltro.rfc) : '') +
(registroFiltro.clase ? '&clase=' + encodeURIComponent(registroFiltro.clase) : ''));
} catch (error) { body.replaceChildren(n('p', error.message, 'error-text')); return; }
if (!body.isConnected) return;
body.replaceChildren();
const filtros = n('div', undefined, 'actions');
const selRfc = select([['', 'Todos los contribuyentes'], ...people.map(person => [person.id, person.id])],
registroFiltro.rfc, 'Contribuyente');
selRfc.onchange = () => { registroFiltro.rfc = selRfc.value; pintar(); };
const selClase = select([['', 'Todo: conexiones, acciones y fallos'], ['conexion', 'Solo conexiones'],
['accion', 'Solo acciones'], ['fallo', 'Solo fallos']], registroFiltro.clase, 'Clase');
selClase.onchange = () => { registroFiltro.clase = selClase.value; pintar(); };



filtros.append(selRfc, selClase);
body.append(filtros);
body.append(n('p', number.format(data.total) + ' suceso(s)' +
(registroFiltro.rfc ? ' de ' + registroFiltro.rfc : '') +
(registroFiltro.clase ? ' · ' + (REGISTRO_CLASE[registroFiltro.clase]?.[1] || registroFiltro.clase) : '') +
' · lo más reciente primero.', 'muted'));
if (!data.items.length) {
body.append(empty('Sin sucesos con ese filtro', 'Cambia el contribuyente o la clase: el registro completo sigue estando, solo está filtrado.'));
return;
}





const list = n('div', undefined, 'activity-list reg-timeline');
let diaActual = '';
for (const item of data.items) {
const dia = new Date(item.at).toLocaleDateString('es-MX',
{ weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
if (dia !== diaActual) {
diaActual = dia;
list.append(n('h3', dia, 'reg-dia'));
}
const [nivel, etiqueta] = REGISTRO_CLASE[item.clase] || ['dim', 'Acción'];
const row = n('div', undefined, 'activity-item' + (item.clase === 'fallo' ? ' reg-fallo' : ''));
const linea = n('div', undefined, 'reg-linea');
linea.append(statusPill(nivel, etiqueta),
n('span', typeof fmtFechaHora === 'function' ? fmtFechaHora(item.at) : '', 'sat-step-time'),
n('span', item.texto +
(item.rfc ? ' · ' + item.rfc : '') +
(item.origen === 'paco' ? ' · lo lanzaste tú' : item.origen === 'sistema' ? ' · lo hizo el sistema solo' : '')));
if (item.evidencia && (item.evidencia.hasShot || item.evidencia.hasHtml)) {
const evidencia = evidenceButtons(item.evidencia.motor,
{ id: item.evidencia.runId, hasShot: item.evidencia.hasShot, hasHtml: item.evidencia.hasHtml });
if (evidencia) linea.append(evidencia);
}
row.append(linea);
if (item.detalle && ((item.detalle.steps || []).length || item.detalle.error)) {
const det = item.detalle;
const details = n('details', undefined, 'reg-detalle');
details.append(n('summary', 'Ver la traza completa del intento'));
const caja = n('div', undefined, 'reg-traza');
for (const step of det.steps || [])
caja.append(n('p', (typeof fmtFechaHora === 'function' ? fmtFechaHora(step.at) : '') + ' · ' +
(step.paso || '') + (step.detalle ? ' — ' + step.detalle : ''), 'reg-step'));
if (det.error) caja.append(n('p', 'Error literal: ' + det.error +
(det.errorKind ? ' (clase: ' + det.errorKind + ')' : ''), 'error-text'));
if ((det.attempts || 0) > 1) caja.append(n('p', 'Intentos de esta corrida: ' + det.attempts, 'muted'));
details.append(caja);
row.append(details);
}
list.append(row);
}
body.append(list);
};
pintar();
return [wrap];
}


async function downloadRegistroCsv() {
try {
const params = [registroFiltro.rfc ? 'rfc=' + encodeURIComponent(registroFiltro.rfc) : '',
registroFiltro.clase ? 'clase=' + encodeURIComponent(registroFiltro.clase) : ''].filter(Boolean).join('&');
download(await satApiBlob('registro/csv' + (params ? '?' + params : '')), 'registro-pacosat.csv');
toast('Registro exportado en CSV.', 'ok');
} catch (error) { toast(error.message, 'error'); }
}
